def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(cells) != 4:
                continue
            minr, maxr = min(y for y, x in cells), max(y for y, x in cells)
            minc, maxc = min(x for y, x in cells), max(x for y, x in cells)
            if maxr - minr != 1 or maxc - minc != 2:
                continue
            row_counts = [sum(y == minr for y, x in cells),
                          sum(y == maxr for y, x in cells)]
            if row_counts == [1, 3]:
                up += 1
            elif row_counts == [3, 1]:
                down += 1

    out = [[0] * 6 for _ in range(3)]
    def draw(n, color, offset):
        if n == 1:
            spots = [(0, 0)]
        elif n == 2:
            spots = [(0, 0), (2, 0)]
        elif n == 3:
            spots = [(0, 0), (0, 2), (2, 0)]
        elif n >= 4:
            spots = [(0, 0), (0, 2), (2, 0), (2, 2)]
        else:
            spots = []
        for y, x in spots:
            out[y][x + offset] = color

    draw(up, 3, 0)
    draw(down, 1, 3)
    return out
